    38	function buildMessageFragmentForValue(
    39	    newValue: string,
    40	    oldValue: string,
    41	    valueName: string,
    42	    valueInQuotes: boolean,
    43	    setFragments: string[],
    44	    removalFragments: string[],
    45	    changeFragments: string[],
    46	    shouldConvertToLowercase = true,
    47	) {
    48	    const newValueToDisplay = valueInQuotes ? `"${newValue}"` : newValue;
    49	    const oldValueToDisplay = valueInQuotes ? `"${oldValue}"` : oldValue;
    50	    const displayValueName = shouldConvertToLowercase ? valueName.toLowerCase() : valueName;
    51	    const isOldValuePartialMerchant = valueName === Localize.translateLocal('common.merchant') && oldValue === CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT;
    52	
    53	    // In case of a partial merchant value, we want to avoid user seeing the "(none)" value in the message.
    54	    if (!oldValue || isOldValuePartialMerchant) {
    55	        const fragment = Localize.translateLocal('iou.setTheRequest', {valueName: displayValueName, newValueToDisplay});
    56	        setFragments.push(fragment);
    57	    } else if (!newValue) {
    58	        const fragment = Localize.translateLocal('iou.removedTheRequest', {valueName: displayValueName, oldValueToDisplay});
    59	        removalFragments.push(fragment);
    60	    } else {
    61	        const fragment = Localize.translateLocal('iou.updatedTheRequest', {valueName: displayValueName, newValueToDisplay, oldValueToDisplay});
    62	        changeFragments.push(fragment);
    63	    }
