    98	function getForDistanceRequest(newMerchant: string, oldMerchant: string, newAmount: string, oldAmount: string): string {
    99	    let changedField: 'distance' | 'rate' = 'distance';
   100	
   101	    if (CONST.REGEX.DISTANCE_MERCHANT.test(newMerchant) && CONST.REGEX.DISTANCE_MERCHANT.test(oldMerchant)) {
   102	        const oldValues = oldMerchant.split('@');
   103	        const oldDistance = oldValues[0]?.trim() || '';
   104	        const oldRate = oldValues[1]?.trim() || '';
   105	        const newValues = newMerchant.split('@');
   106	        const newDistance = newValues[0]?.trim() || '';
   107	        const newRate = newValues[1]?.trim() || '';
   108	
   109	        if (oldDistance === newDistance && oldRate !== newRate) {
   110	            changedField = 'rate';
   111	        }
   112	    } else {
   113	        Log.hmmm("Distance request merchant doesn't match NewDot format. Defaulting to showing as distance changed.", {newMerchant, oldMerchant});
