   116	    const translatedChangedField = Localize.translateLocal(`common.${changedField}`).toLowerCase();
   117	    if (!oldMerchant.length) {
   118	        return Localize.translateLocal('iou.setTheDistanceMerchant', {translatedChangedField, newMerchant, newAmountToDisplay: newAmount});
