   135	function getForReportAction(reportID: string | undefined, reportAction: OnyxEntry<ReportAction>): string {
   136	    if (!ReportActionsUtils.isModifiedExpenseAction(reportAction)) {
   137	        return '';
   138	    }
   139	    const reportActionOriginalMessage = ReportActionsUtils.getOriginalMessage(reportAction);
   140	    const policyID = ReportConnection.getAllReports()?.[`${ONYXKEYS.COLLECTION.REPORT}${reportID}`]?.policyID ?? '-1';
   141	
   142	    const removalFragments: string[] = [];
   143	    const setFragments: string[] = [];
   144	    const changeFragments: string[] = [];
   145	
   146	    const isReportActionOriginalMessageAnObject = reportActionOriginalMessage && typeof reportActionOriginalMessage === 'object';
   147	    const hasModifiedAmount =
   148	        isReportActionOriginalMessageAnObject &&
   149	        'oldAmount' in reportActionOriginalMessage &&
   150	        'oldCurrency' in reportActionOriginalMessage &&
   151	        'amount' in reportActionOriginalMessage &&
   152	        'currency' in reportActionOriginalMessage;
   153	
   154	    const hasModifiedMerchant = isReportActionOriginalMessageAnObject && 'oldMerchant' in reportActionOriginalMessage && 'merchant' in reportActionOriginalMessage;
   155	
   156	    if (hasModifiedAmount) {
   157	        const oldCurrency = reportActionOriginalMessage?.oldCurrency;
   158	        const oldAmountValue = reportActionOriginalMessage?.oldAmount ?? 0;
   159	        const oldAmount = oldAmountValue > 0 ? CurrencyUtils.convertToDisplayString(reportActionOriginalMessage?.oldAmount ?? 0, oldCurrency) : '';
   160	
   161	        const currency = reportActionOriginalMessage?.currency;
   162	        const amount = CurrencyUtils.convertToDisplayString(reportActionOriginalMessage?.amount ?? 0, currency);
   163	
   164	        // Only Distance edits should modify amount and merchant (which stores distance) in a single transaction.
   165	        // We check the merchant is in distance format (includes @) as a sanity check
   166	        if (hasModifiedMerchant && (reportActionOriginalMessage?.merchant ?? '').includes('@')) {
   167	            return getForDistanceRequest(reportActionOriginalMessage?.merchant ?? '', reportActionOriginalMessage?.oldMerchant ?? '', amount, oldAmount);
   168	        }
   169	
   170	        buildMessageFragmentForValue(amount, oldAmount, Localize.translateLocal('iou.amount'), false, setFragments, removalFragments, changeFragments);
   171	    }
   172	
   173	    const hasModifiedComment = isReportActionOriginalMessageAnObject && 'oldComment' in reportActionOriginalMessage && 'newComment' in reportActionOriginalMessage;
   174	    if (hasModifiedComment) {
   175	        buildMessageFragmentForValue(
   176	            reportActionOriginalMessage?.newComment ?? '',
   177	            reportActionOriginalMessage?.oldComment ?? '',
   178	            Localize.translateLocal('common.description'),
   179	            true,
   180	            setFragments,
