   221	            changeFragments,
   222	        );
   223	    }
   224	
   225	    const hasModifiedTag = isReportActionOriginalMessageAnObject && 'oldTag' in reportActionOriginalMessage && 'tag' in reportActionOriginalMessage;
   226	    if (hasModifiedTag) {
   227	        const policyTags = allPolicyTags?.[`${ONYXKEYS.COLLECTION.POLICY_TAGS}${policyID}`] ?? {};
   228	        const transactionTag = reportActionOriginalMessage?.tag ?? '';
   229	        const oldTransactionTag = reportActionOriginalMessage?.oldTag ?? '';
   230	        const splittedTag = TransactionUtils.getTagArrayFromName(transactionTag);
   231	        const splittedOldTag = TransactionUtils.getTagArrayFromName(oldTransactionTag);
   232	        const localizedTagListName = Localize.translateLocal('common.tag');
   233	        const sortedTagKeys = PolicyUtils.getSortedTagKeys(policyTags);
   234	
   235	        sortedTagKeys.forEach((policyTagKey, index) => {
   236	            const policyTagListName = policyTags[policyTagKey].name || localizedTagListName;
   237	
   238	            const newTag = splittedTag[index] ?? '';
   239	            const oldTag = splittedOldTag[index] ?? '';
   240	
   241	            if (newTag !== oldTag) {
   242	                buildMessageFragmentForValue(
   243	                    PolicyUtils.getCleanedTagName(newTag),
   244	                    PolicyUtils.getCleanedTagName(oldTag),
   245	                    policyTagListName,
   246	                    true,
   247	                    setFragments,
   248	                    removalFragments,
   249	                    changeFragments,
   250	                    policyTagListName === localizedTagListName,
   251	                );
   252	            }
   253	        });
   254	    }
   255	
   256	    const hasModifiedTaxAmount = isReportActionOriginalMessageAnObject && 'oldTaxAmount' in reportActionOriginalMessage && 'taxAmount' in reportActionOriginalMessage;
