   263	        buildMessageFragmentForValue(taxAmount, oldTaxAmount, Localize.translateLocal('iou.taxAmount'), false, setFragments, removalFragments, changeFragments);
   264	    }
   265	
   266	    const hasModifiedTaxRate = isReportActionOriginalMessageAnObject && 'oldTaxRate' in reportActionOriginalMessage && 'taxRate' in reportActionOriginalMessage;
   267	    if (hasModifiedTaxRate) {
   268	        buildMessageFragmentForValue(
   269	            reportActionOriginalMessage?.taxRate ?? '',
   270	            reportActionOriginalMessage?.oldTaxRate ?? '',
   271	            Localize.translateLocal('iou.taxRate'),
   272	            false,
   273	            setFragments,
   274	            removalFragments,
   275	            changeFragments,
   276	        );
   277	    }
   278	
   279	    const hasModifiedBillable = isReportActionOriginalMessageAnObject && 'oldBillable' in reportActionOriginalMessage && 'billable' in reportActionOriginalMessage;
   280	    if (hasModifiedBillable) {
   281	        buildMessageFragmentForValue(
   282	            reportActionOriginalMessage?.billable ?? '',
   283	            reportActionOriginalMessage?.oldBillable ?? '',
   284	            Localize.translateLocal('iou.expense'),
   285	            true,
   286	            setFragments,
   287	            removalFragments,
   288	            changeFragments,
   289	        );
   290	    }
   291	
   292	    const hasModifiedReimbursable = isReportActionOriginalMessageAnObject && 'oldReimbursable' in reportActionOriginalMessage && 'reimbursable' in reportActionOriginalMessage;
   293	    if (hasModifiedReimbursable) {
   294	        buildMessageFragmentForValue(
   295	            getBooleanLiteralMessage(reportActionOriginalMessage?.reimbursable, Localize.translateLocal('iou.reimbursable'), Localize.translateLocal('iou.nonReimbursable')),
   296	            getBooleanLiteralMessage(reportActionOriginalMessage?.oldReimbursable, Localize.translateLocal('iou.reimbursable'), Localize.translateLocal('iou.nonReimbursable')),
   297	            Localize.translateLocal('iou.expense'),
   298	            true,
   299	            setFragments,
   300	            removalFragments,
   301	            changeFragments,
   302	        );
   303	    }
   304	
   305	    const message =
   306	        getMessageLine(`\n${Localize.translateLocal('iou.changed')}`, changeFragments) +
   307	        getMessageLine(`\n${Localize.translateLocal('iou.set')}`, setFragments) +
   308	        getMessageLine(`\n${Localize.translateLocal('iou.removed')}`, removalFragments);
   309	    if (message === '') {
   310	        return Localize.translateLocal('iou.changedTheExpense');
   311	    }
   312	    return `${message.substring(1, message.length)}`;
   313	}
